 1	package db_test
 2	
 3	import (
 4		"database/sql"
 5		"os"
 6		"testing"
 7	
 8		"api/internal/db"
 9	
10		_ "github.com/lib/pq"
11	)
12	
13	func testConn(t *testing.T) *sql.DB {
14		t.Helper()
15		url := os.Getenv("TEST_DATABASE_URL")
16		if url == "" {
17			url = "postgres://postgres:postgres@127.0.0.1:5432/appdb?sslmode=disable"
18		}
19		conn, err := db.Connect(url)
20		if err != nil {
21			t.Fatalf("connect: %v", err)
22		}
23		t.Cleanup(func() { conn.Close() })
24		return conn
25	}
26	
27	func TestRunMigrations_IsIdempotent(t *testing.T) {
28		conn := testConn(t)
29	
30		if _, err := conn.Exec(`DROP TABLE IF EXISTS items, schema_migrations`); err != nil {
31			t.Fatalf("reset: %v", err)
32		}
33	
34		if err := db.RunMigrations(conn, "../../migrations"); err != nil {
35			t.Fatalf("first run: %v", err)
36		}
37		if err := db.RunMigrations(conn, "../../migrations"); err != nil {
38			t.Fatalf("second run should be a no-op, got error: %v", err)
39		}
40	
41		var count int
42		if err := conn.QueryRow(`SELECT COUNT(*) FROM schema_migrations`).Scan(&count); err != nil {
43			t.Fatalf("count migrations: %v", err)
44		}
45		if count != 1 {
46			t.Fatalf("expected exactly 1 recorded migration, got %d", count)
47		}
48	}
